const market = (
  token: string,
  launchpad: LaunchMarket['launchpad'],
  quote: string,
): LaunchMarket => ({ token, launchpad, quote });

describe('elysium launchpad decoders', () => {
  it('decodes a CorePad launch with its creator, curve, name and symbol', () => {
    const l = decodeLaunch(corepadLaunch);
    expect(l).toMatchObject({
      token: '0x9980d3934c71c885359de3f5aa20a26ecee412c5',
      launchpad: 'CorePad',
      kind: 'curve',
      creator: '0x97a62b5d5fd2989cf8f368c54edd7384df9a0432',
      curve: '0x612b3699e80f5944d4bdd2f6d2f1f853a87f7b11',
      symbol: 'ATLAS',
    });
  });

  it('decodes a Signal curve launch with its V2 pair as the post-graduation market', () => {
    const l = decodeLaunch(signalCurveLaunch);
    expect(l).toMatchObject({ launchpad: 'Signal', kind: 'curve', creator: null });
    expect(launchMarketKeys(l!)).toEqual([l!.curve, l!.pool]);
  });

  it('decodes Chainzy and Signal V4 launches', () => {
    expect(decodeLaunch(chainzyLaunch)).toMatchObject({
      token: '0x82c8d39b7841f8d4db270d243ed90d48dd958888',
      launchpad: 'Chainzy',
      kind: 'v3',
      creator: '0xd18057df637a394a1c195d74ccc4fe33e85a0995',
    });
    expect(decodeLaunch(signalV4Launch)).toMatchObject({ launchpad: 'Signal', kind: 'v4' });
  });

  it('ignores a launch event emitted by an unknown contract', () => {
    expect(
      decodeLaunch({ ...corepadLaunch, address: '0x000000000000000000000000000000000000dead' }),
    ).toBeNull();
  });

  it('decodes the Chainzy creator buy from its V3 swap', () => {
    const l = decodeLaunch(chainzyLaunch)!;
    const markets = new Map([[l.pool!, market(l.token, 'Chainzy', l.quote)]]);
    const t = decodeLaunchTrade(v3Swap, markets);
    expect(t).toMatchObject({ venue: 'v3', is_buy: true, quote_amount: '5500000000000000000' });
    expect(Number(t!.token_amount) / 1e18).toBeCloseTo(97_140_547.37, 1);
  });

  it('decodes a V4 swap on a Signal pool as a buy', () => {
    const l = decodeLaunch(signalV4Launch)!;
    const markets = new Map([[l.pool!, market(l.token, 'Signal', l.quote)]]);
    expect(decodeLaunchTrade(v4Swap, markets)).toMatchObject({
      venue: 'v4',
      is_buy: true,
      trader: null,
    });
  });

  it('decodes CorePad curve and Signal router trades for known curves only', () => {
    const corepadCurve = corepadTrade.address;
    const signalCurve = `0x${signalRouterTrade.topic1.slice(-40)}`;
    const markets = new Map([
      [
        corepadCurve,
        market(
          '0x1111111111111111111111111111111111111111',
          'CorePad',
          '0x0000000000000000000000000000000000000000',
        ),
      ],
      [
        signalCurve,
        market(
          '0x2222222222222222222222222222222222222222',
          'Signal',
          '0xcd57f65c2b0e5881cfc2e609f7cd53b746e1f234',
        ),
      ],
    ]);
    const cp = decodeLaunchTrade(corepadTrade, markets);
    expect(cp).toMatchObject({ venue: 'curve', is_buy: true });
    expect(cp!.price).toBeGreaterThan(0);
    const sg = decodeLaunchTrade(signalRouterTrade, markets);
    expect(sg).toMatchObject({ venue: 'curve', is_buy: true });
    expect(decodeLaunchTrade(corepadTrade, new Map())).toBeNull();
  });

  it('reads graduation from either curve event', () => {
    const g = decodeGraduation({ ...corepadTrade, topic0: LAUNCHPAD_TOPICS.signalGraduated });
    expect(g).toEqual({ curve: corepadTrade.address, graduated_at: '2026-10-01T00:00:00.000Z' });
  });

  it('turns a sqrtPriceX96 into quote per token on either side of the pool', () => {
    const sqrt = BigInt(2) ** BigInt(96) * BigInt(2); // currency1 per currency0 = 4
    expect(priceFromSqrt(sqrt, true)).toBeCloseTo(4);
    expect(priceFromSqrt(sqrt, false)).toBeCloseTo(0.25);
  });
});
